window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II y oraciones con wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Si yo fuera tú, …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"La realidad de Eva – los deseos de Eva. Completa: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Pero le gustaría ser más alta.","why":"*grösser sein*: la forma de deseo de *sein* es **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Pero le gustaría hablar bien español.","why":"Hay un infinitivo al final (*sprechen*), así que el deseo es **würde** + infinitivo.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Pero preferiría trabajar como guía turística.","why":"Infinitivo al final (*arbeiten*) → **würde** + infinitivo. *lieber* = más bien / preferiblemente.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Pero le gustaría tener un apartamento grande.","why":"*eine Wohnung haben*: la forma de deseo de *haben* es **hätte**. No hace falta infinitivo.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"¿Qué piensan las personas?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Relaciona cada imagen con una expresión del recuadro.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Si no tuviera que trabajar, ahora estaría sentado en el jardín.","why":"La imagen 1 lo muestra trabajando y luego soñando en una tumbona. Después de una oración con *wenn*, la oración principal empieza por el verbo (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Si tuviera coche, no tendría que ir en bici bajo la lluvia.","why":"Va en bici bajo la lluvia; con un coche se lo ahorraría. *müsste* es el Konjunktiv II de *müssen*. *Velo* es la palabra suiza para *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Si el autobús no llegara con retraso, llegaría puntual a la oficina.","why":"Como el autobús va con retraso, ella llega tarde al trabajo. *wäre* es el Konjunktiv II de *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Reescribe las frases de a: empieza con la oración principal y luego la oración con wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"No tendría que ir en bici bajo la lluvia si tuviera coche.","why":"Primero la oración principal y luego la oración con *wenn*. En la oración con *wenn* el verbo (*hätte*) va al final.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Llegaría puntual a la oficina si el autobús no llegara con retraso.","why":"El mismo esquema: oración principal, coma, *wenn* … verbo al final (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Completa con las palabras del recuadro. Cada palabra se usa una vez; las tachadas se usan en el ejemplo.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Haría algunas cosas de otra manera si yo fuera la jefa de nuestra empresa.","why":"*machen* al final → **würde** + infinitivo. *Chefin sein* → **wäre**, al final de la oración con *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Si yo fuera Marco, haría sin falta una formación profesional.","why":"*Marco sein* → **wäre** (como en *Wenn ich du wäre …*). La oración principal tiene el infinitivo *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Si pudiera decidir libremente, trabajaría en una empresa pequeña.","why":"*frei entscheiden können* → **könnte** al final de la oración con *wenn*. Oración principal con *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Si tuviéramos hijos, solo tendría que trabajar media jornada.","why":"*Kinder haben* con *wir* → **hätten**. El recuadro deja **müsste** para el último hueco.","source":"k2","check":"*müsste* y *würde* son alemán correcto en b, c y e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* está igual de bien). El recuadro solo dice qué tres huecos llevan *würde* y cuál lleva *müsste*; esta clave es el reparto más probable. Pregunta a tu profesor cuál quiere el libro."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Tengo que darme prisa por mi trabajo.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Reescribe las respuestas con weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Porque mi novia es impuntual.","why":"*wegen* + sustantivo se convierte en *weil* + una oración con verbo; el verbo (*ist*) va al final.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Porque hace mal tiempo.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; después de *weil* el verbo va al final.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Porque tengo una cita importante.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (acusativo después de *haben*); verbo al final.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Completa: wegen – weshalb – weil – deswegen – denn. Una palabra puede usarse más de una vez.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"Lo entiendo mal por su pronunciación.","why":"Sigue un sustantivo (*seiner Aussprache*, genitivo), no una oración → la preposición **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Algún día me gustaría viajar a Italia, porque me gustaría ver el mar.","why":"El verbo se queda en 2.ª posición después del hueco (*ich möchte*) → **denn**. Con *weil* iría al final.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Tengo que mejorar mi comprensión auditiva, por eso veo muchas películas.","why":"La segunda parte es la consecuencia, y el verbo va justo después del hueco (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"Mis hijos aprendieron alemán rápido porque en el jardín de infancia siempre están con niños suizos.","why":"El verbo está al final (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"¿Por qué escribes las palabras en tarjetitas?","why":"Hace falta una palabra interrogativa: **Weshalb** significa *warum* (por qué)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Mi hermana ya habla alemán casi con fluidez, por eso puede ayudarme a aprender alemán.","why":"Consecuencia, y el verbo va justo después del hueco (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"En el curso de idiomas. Completa: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"No pude hacer el último ejercicio porque no lo entendí.","why":"El verbo está al final (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"En la inscripción no había nadie. Por eso volví a casa.","why":"Una frase nueva que da la consecuencia, con el verbo justo después del hueco (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Por mis buenas notas no tuve que hacer ninguna prueba al comienzo del curso.","why":"Sigue un grupo nominal (*meiner guten Noten*, genitivo plural) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"Hay un curso de idiomas extra porque se han inscrito muchísimos participantes.","why":"El verbo está al final (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Ayer, por desgracia, no pude venir al curso por mi dolor de muelas.","why":"Sigue un grupo nominal (*meiner Zahnschmerzen*, genitivo plural) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"¿Quién encuentra las mejores excusas? Elige una situación y escribe. Cada respuesta modelo es solo una posibilidad.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Por desgracia no pude ordenar la cocina porque de repente tuve un fuerte dolor de espalda. Tuve que acostarme. Por eso vi una película.","why":"Usa *weil* (verbo al final: *hatte*) y *Deswegen* (verbo justo después: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"Por una gripe no fui al examen final. Tenía fiebre alta, por eso me quedé en la cama.","why":"Usa *wegen* + genitivo (*einer Grippe*) y *deswegen* + verbo (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"¡Lo siento muchísimo! Por desgracia he llegado tarde, porque había un accidente en la autopista. Por el atasco perdí dos horas.","why":"*denn* deja el verbo en 2.ª posición (*war*). *wegen des Staus*: genitivo de *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (oraciones condicionales, también las irreales con Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"grammis, diccionario de conectores: wenn (subordinante, verbo al final)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"grammis, diccionario de conectores: weil (subordinante, verbo al final)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, diccionario de conectores: denn (causal, el verbo se queda en 2.ª posición)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis, diccionario de conectores: deswegen (consecuencia; va delante del verbo o en medio)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen con genitivo)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Crecer con varios idiomas · lectura, mensaje de foro, crucigrama, palabras favoritas","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"En casa con varios idiomas","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Dos o tres idiomas en una familia: ¿sin problema?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"¿Quién dice qué? Lee los tres textos y escribe el nombre de la persona que dice cada frase.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"“Los niños quieren hablar el mismo idioma que sus amigos.” – Janusz","why":"Janusz (texto B): *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"“Está bien hablar varios idiomas muy bien, ¿no?” – Yara","why":"Yara (texto C): *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"“Mis hijos cambian entre dos idiomas.” – Amira","why":"Amira (texto A): *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* Es la única que habla de sus propios hijos."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"¿Qué es correcto? Vuelve a leer los textos. Escribe *richtig* (correcto) o *falsch* (falso) después de cada frase; en el libro solo marcas las correctas.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"Los hijos de Amira hablan árabe mejor que alemán. → correcto","why":"En casa la familia siempre habla árabe: *Darum können das die Kinder viel besser.* (Su alemán aquí es el alemán suizo.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"En la familia de Amira solo se habla alemán. → falso","why":"Justo lo contrario: *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz estudió alemán durante seis años. → falso","why":"Tenía seis años cuando la familia se mudó (*als ich sechs Jahre alt war*), y al cabo de un año hablaba alemán estándar con fluidez."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz y su hermana no querían hablar polaco con sus padres. → correcto","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara habla tres idiomas con fluidez. → correcto","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* El alemán es su cuarto idioma y todavía no lo habla bien."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara va a empezar a aprender alemán también pronto. → falso","why":"No va a empezar pronto (*bald*): ya lleva dos años aprendiendo alemán (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"En casa con varios idiomas","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Escribir un mensaje de foro. Has visto un debate de televisión sobre crecer con varios idiomas. En el foro en línea del programa encuentras esta opinión:","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Toma notas sobre las cuatro preguntas. Bastan notas breves, sin frases completas. Las notas modelo son una posibilidad.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Sí: el hijo de mi vecina – italiano con su madre, alemán suizo en el colegio","why":"Solo notas: un nombre o una persona, y qué idiomas en qué sitio."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"aprender dos idiomas sin curso, contacto con la familia en el extranjero, ventajas en el trabajo","why":"Reúne dos o tres ventajas; las necesitas para *Ich finde es sehr gut, dass …* en b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mezclar los idiomas, un idioma es más débil, mucho trabajo para los padres","why":"Estas van en *Es könnte schwierig sein, dass …* y *Auf der anderen Seite …* en b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"no – los niños aprenden bien dos idiomas si sus padres hablan mucho con ellos","why":"Decide sí o no y da una razón: eso se convierte en *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Ahora escribe tu opinión sobre el tema (unas 80 palabras). Usa tus notas de a y algunas de las expresiones.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"No estoy de acuerdo con Sandra, porque muchos niños aprenden dos idiomas sin problemas. El hijo de mi vecina crece con italiano y alemán. Con su madre habla italiano y en el colegio alemán suizo. Me parece muy bien que aprenda dos idiomas tan pronto. Podría ser difícil que a veces mezcle los idiomas. Por otro lado, eso es normal en los niños pequeños. Lo más importante de todo es que los padres hablen mucho con el niño. Por eso cada progenitor debería hablar su propio idioma.","why":"Unas 85 palabras, con seis de las expresiones. *denn* mantiene el verbo en segunda posición (*lernen*); después de *Deswegen* el verbo va inmediatamente después (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Resuelve el crucigrama. Cada frase da la primera letra de la palabra que falta. Aquí no se muestra la cuadrícula: escribe la palabra completa. En la cuadrícula del libro la Ä ocupa una casilla.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Nuestro país de origen es España. Procedemos de España.","why":"*aus einem Land stammen* = proceder de un país (como *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda y Mike no se ven durante seis meses. Es una separación larga.","why":"*die Trennung* = separación, el sustantivo de *sich trennen*. *eine lange* → un sustantivo femenino."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"El alemán y el árabe no tienen la misma escritura.","why":"*die Schrift* = escritura, las letras con que se escribe un idioma. El árabe usa otro alfabeto."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter vive ahora en América. Desde que vive allí, ha cambiado mucho.","why":"*sich verändern* = cambiar (como persona). Perfekt: *hat sich verändert*. La Ä ocupa una casilla."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"Ella escribe libros. Es autora de profesión.","why":"*Sie* → la forma femenina con *-in*: *der Autor → die Autorin*. Sin artículo después de *sein … von Beruf*."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"Los niños no hacen los deberes. Por eso sus padres los regañan.","why":"*mit jemandem schimpfen* = regañar a alguien. Sujeto plural *die Eltern* → *schimpfen*. Después de *Deshalb* el verbo va inmediatamente después."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"Solo lleva trabajando unos meses. Todavía tiene poca experiencia en su trabajo.","why":"*die Erfahrung* = experiencia. *wenig Erfahrung haben* = tener poca experiencia."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Ahora tenemos un caos. Todo está revuelto.","why":"*durcheinander sein* = estar revuelto, desordenado. Se escribe en una sola palabra."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"Para Ye-Jon los sonidos P y F suenan igual. No sabe distinguirlos.","why":"*unterscheiden* = distinguir. Con *kann* el infinitivo va al final. *tönen* es la forma suiza de *klingen* (sonar)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"Voy a Grecia de vacaciones, pero por desgracia no sé nada de griego.","why":"*Griechisch* = el idioma griego, con mayúscula. *kein Griechisch können* = no saber nada de griego."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"Solo come verdura y arroz. Come exclusivamente verdura y arroz.","why":"*ausschliesslich* = exclusivamente, nada más que. Ortografía suiza con *ss*; en Alemania se escribe con la s aguda (Eszett)."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Palabra solución (la fila resaltada de la cuadrícula): lengua materna","why":"Cada palabra aporta una letra de la fila resaltada: stam**M**en, trenn**U**ng, schrif**T**, (T en la cuadrícula), veränd**E**rt, auto**R**in, (S en la cuadrícula), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"En casa con varios idiomas","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"Mi palabra alemana más bonita","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Une cada foto con una palabra del recuadro. Los puntos de color del libro indican el artículo: azul = der, verde = das, rojo = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (un postre de natillas con caramelo)","why":"Nombre suizo del crème caramel. *Chöpfli* es alemán suizo para “cabecita” (*Kopf*). Punto verde → *das*."},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – estrella fugaz","why":"*der Stern* = estrella; *die Sternschnuppe* = estrella fugaz. Punto rojo → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – mariposa","why":"Palabra suiza para *der Schmetterling* (mariposa); el Duden la marca como *schweizerisch, sonst landschaftlich*. Punto azul → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"¿Por qué alguien podría encontrar precisamente estas palabras las más bonitas? ¿Qué piensas? Toma notas y luego habla de ellas. Las notas modelo son una posibilidad.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"tan colorida y ligera, recuerda al verano, gracioso: el animal no es un pájaro en absoluto","why":"Piensa en lo que te hace ver o sentir la palabra, y en cómo suena."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"dulce, recuerda a la infancia, suena gracioso y típicamente suizo","why":"*tönen* = forma suiza de *klingen* (sonar)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romántica, se puede pedir un deseo, suena suave","why":"Bastan notas breves: adjetivos y una razón."}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"Mi palabra favorita","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"¿Qué palabra alemana y qué palabra de tu lengua materna te gustan? ¿Por qué? Escribe un texto breve usando las expresiones. La respuesta modelo es una posibilidad.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"Mi palabra alemana favorita es “gemütlich” (acogedor). Cuando oigo esta palabra, pienso en una tarde de invierno con té, velas y amigos. Por eso me parece tan bonita. Suena suave y cálida. En mi lengua materna, el inglés, no hay ninguna palabra con exactamente este significado. En inglés me gusta la palabra “sunshine”. Para mí es una palabra alegre, porque suena luminosa y amable.","why":"*Wenn …, dann* + verbo inmediatamente después (*denke ich*); *Deshalb* + verbo inmediatamente después (*finde ich*). Cambia por tu propia lengua materna y tus propias palabras.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Presenta tu texto en clase. En el modelo se muestra una posible forma de empezar.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Hoy me gustaría presentaros mi palabra favorita. Es la palabra “gemütlich”. …","why":"Empieza nombrando la palabra y luego lee tu texto de a. *euch* para los compañeros, *Ihnen* si hablas de usted."}]}]}],"sources":[{"id":"sommervogel","title":"Duden: Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"grammis, diccionario de conectores: deswegen (consecuencia; va antes del verbo o en medio)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"grammis, diccionario de conectores: wenn (subordinante, verbo al final)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]}];
